function label(id){const x=read().series.find(x=>x.id===id);return x?x.code+' · '+x.name:'—';}
function valid(id){return !id||read().series.some(x=>x.id===id&&x.enabled&&!x.deleted);}
function check(id){if(!valid(id)){notify('产品系列已禁用、删除或不存在，请重新选择','error');return false;}return true;}
function ref(id){const s=read();return s.materials.some(m=>m.seriesId===id)||Object.values(s.records).some(r=>r.seriesId===id)||Object.values(s.forms).some(r=>r.seriesId===id);}
let counter=0;
function modal(title,content,options={}){
 const d=document.createElement('dialog');d.className='proto-modal series-dialog';d.id='series-dialog-'+(++counter);d.setAttribute('aria-labelledby',d.id+'-title');
 d.innerHTML=`<div class="series-dialog-head"><h2 id="${d.id}-title">${E(title)}</h2><button type="button" class="proto-btn proto-icon-btn" aria-label="关闭弹窗" data-close><svg class="prototype-icon" aria-hidden="true"><use href="assets/icons/prototype-icons.svg#icon-close"></use></svg></button></div><div class="series-dialog-body">${content}</div><div class="series-dialog-footer"><button type="button" class="proto-btn" data-close>${E(options.cancel||'取消')}</button>${options.confirm===false?'':`<button type="button" class="proto-btn proto-btn--primary" data-confirm>${E(options.confirm||'确认')}</button>`}</div>`;
 document.body.append(d);const opener=document.activeElement;d.showModal();const release=PrototypeUI.trapDialogFocus(d,opener);const closeAllowed=()=>!$('[data-confirm]',d)?.disabled;$$('[data-close]',d).forEach(b=>b.onclick=()=>{if(closeAllowed())d.close();});d.addEventListener('proto:request-close',()=>{if(closeAllowed())d.close();});d.addEventListener('cancel',e=>{if(!closeAllowed())e.preventDefault();});d.addEventListener('close',()=>{release();d.remove();},{once:true});return d;
}
function error(d,text){let e=$('[data-error]',d);if(!e){e=document.createElement('div');e.dataset.error='';e.className='series-error';e.role='alert';$('.series-dialog-body',d).append(e);}e.textContent=text;}
function confirmAction(title,text,fn){const d=modal(title,`<p>${E(text)}</p>`);$('[data-confirm]',d).onclick=async e=>{PrototypeUI.setButtonBusy(e.target,true,'处理中…');await new Promise(r=>setTimeout(r,260));try{if(fn()!==false)d.close();}finally{PrototypeUI.setButtonBusy(e.target,false);}};return d;}
function compactPicker(title,getRows,current,apply){
 let page=1,query='';const size=10;
 const d=modal(title,`<form class="compact-picker-search"><label class="series-visually-hidden" for="compactPickerQuery">名称</label><input id="compactPickerQuery" class="proto-input" placeholder="请输入名称" autocomplete="off"><button type="submit" class="proto-btn proto-btn--primary" aria-label="查询" title="查询"><svg class="prototype-icon" aria-hidden="true"><use href="assets/icons/prototype-icons.svg#icon-search"></use></svg></button></form><div class="compact-picker-table"><table><thead><tr><th>编码</th><th>名称</th></tr></thead><tbody data-compact-rows></tbody></table></div><nav class="compact-picker-pages" aria-label="选择列表分页"></nav>`,{confirm:false});
 d.classList.add('series-compact-picker');$('.series-dialog-footer',d).remove();
 function draw(){const rows=getRows().filter(x=>x.name.includes(query));const pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(page,pages);$('[data-compact-rows]',d).innerHTML=rows.slice((page-1)*size,page*size).map(x=>`<tr tabindex="0" role="button" aria-label="选择${E(x.code+' '+x.name)}" aria-pressed="${x.id===current}" data-choice="${E(x.id)}"><td>${E(x.code)}</td><td title="${E(x.name)}">${E(x.name)}</td></tr>`).join('')||'<tr><td colspan="2" class="series-empty">暂无数据</td></tr>';
 $$('[data-choice]',d).forEach(row=>{const select=()=>{const x=getRows().find(x=>x.id===row.dataset.choice);if(!x){draw();return notify('数据已失效，请重新选择','error');}apply(x);d.close();};row.onclick=select;row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});
 $('.compact-picker-pages',d).innerHTML=`<span>${rows.length}条数据</span><button type="button" class="proto-btn" aria-label="上一页" title="上一页" data-page="${page-1}" ${page===1?'disabled':''}><svg class="prototype-icon compact-prev" aria-hidden="true"><use href="assets/icons/prototype-icons.svg#icon-chevron-right"></use></svg></button>${Array.from({length:pages},(_,i)=>i+1).filter(n=>n===1||n===pages||Math.abs(n-page)<=1).map(n=>`<button type="button" class="proto-btn ${n===page?'proto-btn--primary':''}" data-page="${n}" ${n===page?'aria-current="page"':''}>${n}</button>`).join('')}<button type="button" class="proto-btn" aria-label="下一页" title="下一页" data-page="${page+1}" ${page===pages?'disabled':''}><svg class="prototype-icon" aria-hidden="true"><use href="assets/icons/prototype-icons.svg#icon-chevron-right"></use></svg></button>`;$$('[data-page]',d).forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);draw();});
 }
 $('.compact-picker-search',d).onsubmit=e=>{e.preventDefault();query=$('#compactPickerQuery',d).value.trim();page=1;draw();};draw();$('#compactPickerQuery',d).focus();return d;
}
