function workbook(name,headers,rows){if(!window.XLSX){notify('Excel组件未加载，请刷新后重试','error');return false;}const wb=XLSX.utils.book_new();const ws=XLSX.utils.aoa_to_sheet([headers,...rows]);ws['!cols']=headers.map(()=>({wch:23}));XLSX.utils.book_append_sheet(wb,ws,'数据');XLSX.writeFile(wb,name);return true;}
function taskCreate(task){const s=read();if(task.forceFail){task.success=0;task.failed=task.total;}task={...task,id:'TASK-'+Date.now(),created:new Date().toLocaleString('zh-CN'),status:'处理中',doneAt:Date.now()+1600};s.tasks.unshift(task);write(s);setTimeout(()=>{settleTasks();tasksPanel();},1700);return task;}
function settleTasks(){const s=read();let changed=false;s.tasks.forEach(t=>{if(t.status==='处理中'&&Date.now()>=t.doneAt){if(t.kind==='import'&&t.changes){t.changes.forEach(change=>{const m=s.materials.find(x=>x.code===change.code);if(m){if(change.lineCode)m.lineCode=change.lineCode;if(change.seriesId)m.seriesId=change.seriesId;s.log.push({code:change.code,time:new Date().toISOString(),action:'批改产品线/产品系列',task:t.id});}});delete t.changes;}t.status=t.kind==='import'?(t.failed===t.total?'失败':t.failed?'部分成功':'成功'):t.forceFail?'失败':'成功';changed=true;}});if(changed)write(s);}
function tasksPanel(){settleTasks();const root=$('[data-series-tasks]');if(!root)return;const tasks=read().tasks;const signature=JSON.stringify(tasks);if(root.dataset.render===signature)return;root.dataset.render=signature;root.innerHTML=tasks.length?`<div class="proto-table-wrap"><table class="proto-table"><thead><tr><th>任务编号 / 类型</th><th>创建时间</th><th>状态</th><th>总数</th><th>成功</th><th>失败</th><th>操作</th></tr></thead><tbody>${tasks.map(t=>`<tr><td>${E(t.id)}<br>${t.kind==='export'?'自定义导出':'产品线/产品系列批改'}</td><td>${E(t.created)}</td><td>${E(t.status)}</td><td>${t.total}</td><td>${t.status==='处理中'?'—':t.success}</td><td>${t.status==='处理中'?'—':t.failed}</td><td><button class="proto-btn" type="button" data-task-detail="${E(t.id)}">查看结果</button>${t.status==='处理中'?'':`<button class="proto-btn" type="button" data-task-download="${E(t.id)}">${t.kind==='export'?'下载文件':'下载逐行结果'}</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<p class="series-muted">暂无产品系列演示任务，可从自定义导出或导入批改创建。</p>';
 $$('[data-task-detail]',root).forEach(b=>b.onclick=()=>taskDetail(b.dataset.taskDetail));$$('[data-task-download]',root).forEach(b=>b.onclick=()=>taskDownload(b.dataset.taskDownload));}
function taskDetail(id){settleTasks();const t=read().tasks.find(x=>x.id===id);if(!t)return;const d=modal('任务结果',`<p>${E(t.id)}　${E(t.status)}</p><p>总数 ${t.total}　成功 ${t.status==='处理中'?'—':t.success}　失败 ${t.status==='处理中'?'—':t.failed}</p>${t.status==='处理中'?'<p>任务处理中，完成后可刷新查看。</p>':t.forceFail?'<p class="series-error">导出失败：生成文件服务不可用，请重试</p>':t.kind==='export'?'<p>已按本次勾选字段生成示例文件，编码使用文本保留前导零。</p>':`<div class="proto-table-wrap"><table class="proto-table"><thead><tr><th>行号</th><th>物料编码</th><th>结果</th><th>原因</th></tr></thead><tbody>${t.results.map(r=>`<tr><td>${r.line}</td><td>${E(r.code)}</td><td>${E(r.ok?'成功':'失败')}</td><td>${E(r.reason)}</td></tr>`).join('')}</tbody></table></div>`}`,{confirm:t.status==='处理中'?'刷新结果':t.forceFail?'关闭':'下载结果'});$('[data-confirm]',d).onclick=()=>{d.close();if(t.status==='处理中')taskDetail(id);else if(!t.forceFail)taskDownload(id);};}
function taskDownload(id){settleTasks();const t=read().tasks.find(x=>x.id===id);if(!t||t.status==='处理中')return notify('任务尚未完成');if(t.forceFail)return notify('任务失败，未生成文件','error');if(t.kind==='export')workbook('自定义导出-'+id+'.xlsx',t.headers,t.rows);else workbook('批改逐行结果-'+id+'.xlsx',['行号','物料编码','处理结果','错误原因'],t.results.map(r=>[r.line,r.code,r.ok?'成功':'失败',r.reason]));}
function downloadSeriesTemplate(){const a=document.createElement('a');a.href='assets/templates/产品线产品系列批改模板.xlsx?v=20261109';a.download='产品线产品系列批改模板.xlsx';document.body.append(a);a.click();a.remove();}
