 let input=$('#seriesDirectFile');if(!input){input=document.createElement('input');input.id='seriesDirectFile';input.type='file';input.accept='.xlsx,.xls';input.hidden=true;input.setAttribute('aria-label','选择产品线产品系列批改文件');$('#modalBatchModify').append(input);input.onchange=()=>{const f=input.files[0];if(!f)return;const d=fileImport();const target=$('#seriesImportFile',d);const transfer=new DataTransfer();transfer.items.add(f);target.files=transfer.files;target.dispatchEvent(new Event('change',{bubbles:true}));};}input.value='';input.click();
