 const sync=()=>{const selected=$('#customExportSelected');if(!selected||!fields)return;const inputs=$$('input[type=checkbox]',fields);selected.innerHTML=inputs.filter(x=>x.checked).map(x=>`<li class="${x.disabled?'disabled':''}"><input type="checkbox" checked ${x.disabled?'disabled':''} data-selected-field="${E(x.getAttribute('aria-label'))}" aria-label="移除${E(x.getAttribute('aria-label'))}">${E(x.getAttribute('aria-label'))}</li>`).join('');const count=selected.closest('.field-panel')?.querySelector('.field-panel-head span');if(count)count.textContent='已选字段（共'+inputs.filter(x=>x.checked).length+'个）';$$('[data-selected-field]',selected).forEach(b=>b.onchange=()=>{inputs.find(x=>x.getAttribute('aria-label')===b.dataset.selectedField).checked=b.checked;sync();});};
 if(fields){fields.addEventListener('change',sync);sync();$('#customExportClear')?.addEventListener('click',()=>{$$('input:not(:disabled)',fields).forEach(x=>x.checked=false);sync();});const search=$('#modalCustomExport .export-search');if(search)search.oninput=()=>$$('li',fields).forEach(li=>{li.hidden=!li.textContent.includes(search.value.trim());li.style.display=li.hidden?'none':'';});}
 $('#customExportSubmit')?.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();const headers=$$('input:checked',fields).map(x=>x.getAttribute('aria-label'));if(!headers.length)return notify('请至少选择一个字段','error');const d=modal('确认自定义导出',`<p>已选 ${headers.length} 个字段，将生成当前可见示例物料的 Excel 文件。</p><p>${headers.map(E).join('、')}</p><label><input type="checkbox" data-fail-demo> 演示任务生成失败</label><p class="series-muted">沿既有导出权限和审批要求。该弹窗演示任务受理，实际生产审批仍由原流程决定。</p>`,{confirm:'提交导出任务'});$('[data-confirm]',d).onclick=async e=>{PrototypeUI.setButtonBusy(e.target,true,'提交中…');await new Promise(r=>setTimeout(r,350));const state=read();const rows=state.materials.map(m=>headers.map(h=>{const si=state.series.find(x=>x.id===m.seriesId);return h==='产品系列编码'?si?.code||'':h==='产品系列'?si?.name||'':h==='产品线编码'?m.lineCode||'':h==='产品线'?(m.lineName||({'001':'工业工具','002':'电气设备','004':'工业工具'}[m.lineCode])||''):h==='物料（编码）'?m.code:h==='物料（名称）'?m.name:h==='型号'?m.model:h.includes('货主')?m.org:'';}));taskCreate({kind:'export',headers,rows,total:rows.length,success:rows.length,failed:0,forceFail:$('[data-fail-demo]',d).checked});$('#modalCustomExport').classList.remove('show');d.close();notify('导出任务已受理，可在任务中心查看状态');showTaskEntry();};},true);
